-- Schede nuove dalle pagine RHS (controllo periodico del 19/11/2026): 31 specie del catalogo senza
-- nessuna scheda. Testi in italiano scritti a mano (scripts/rhs-import/dati/), in bozza e mostrate.
-- Generata da scripts/rhs-import/schede_nuove.py. Rollback: scripts/rhs-import/rollback_rhs_schede_nuove_lotto1.sql
do $$ begin
  if exists (select 1 from public.schede where taxon_id in ('f741411a-7582-42bf-b4d9-5eb31e6f434f'::uuid, '04497ebd-3dc2-4642-a72c-59fc8bdfbea1'::uuid, '2a24852a-d58f-44b7-bf08-69ef710a816e'::uuid, 'f6454a97-f607-4e24-8131-5e1cd8d0e579'::uuid, '0e7863e8-84bb-4872-bf14-362cd5ac4aec'::uuid, 'cd2e45be-d28a-453b-af61-3d9b9208c5dd'::uuid, 'cabe52ec-bbf5-4b84-8627-e0568d098ae7'::uuid, 'd34fc5db-5657-4120-bbb7-8d0d74a938d9'::uuid, 'a581c6c0-16de-4e3d-a392-921008e9d532'::uuid, 'fa56dc21-4ab5-45cc-9d80-0fe7c84bd42f'::uuid, '91af781c-6eab-4f25-b7ef-dd2a8e8e1fcb'::uuid, '2d41b267-5b30-4eee-b4d6-c0d0c319f373'::uuid, 'fbf54553-0fc8-4461-941d-d1fa9756a368'::uuid, 'f900cad5-1161-4078-9802-7d7792b1505f'::uuid, '2d2c3eb8-1fc2-45bc-bb30-e9cf13c38e43'::uuid, 'bf4f5f44-d15a-4240-95ec-e91cdd540af2'::uuid, '5aaf816c-bf02-46e7-a4cf-f0f57e49d2ae'::uuid, 'ff4f1ea4-8a55-40d9-abf7-4592d36087de'::uuid, 'c50023a0-2b0f-4578-afda-3dc753840cec'::uuid, 'e31c9865-a817-4c85-868d-5a750ca12890'::uuid, 'dd86bc72-1075-4fcd-b8dd-9eb5b7b3f2a1'::uuid, 'abd2fe15-a7f8-48a9-9770-750928518079'::uuid, '006a484b-7851-423f-9063-f7ec5a97fce8'::uuid, 'a9753ea9-c937-443d-8b6c-4ccea65eee9b'::uuid, '3003dfd6-ede6-4454-9e55-f36e7491aa31'::uuid, '113e4bc9-5321-40af-acee-565925b3d8d2'::uuid, '37398db8-70b3-48a4-97ba-4b60fc8e3582'::uuid, '35c48318-3871-4a58-b56f-40a370e7a484'::uuid, '3b5582bc-b452-4046-8f99-d3e09cae1c7b'::uuid, '1e944339-02ab-46cf-ba88-460c9affd666'::uuid, 'd22573b0-c3aa-4f4e-8a02-72979e01bbbd'::uuid)) then
    raise exception 'una di queste specie ha già una scheda: lotto da rigenerare';
  end if;
end $$;
insert into public.schede (id, taxon_id, fonti, descrizione, descrizione_originale, lingua_descrizione, esigenze,
  ciclo_vitale, alert, stato_verifica, mostrata, forma, nota) values
('0bea6986-f036-5e8d-9afb-9b4400368bf8'::uuid, 'f741411a-7582-42bf-b4d9-5eb31e6f434f'::uuid, array['RHS (rhs.org.uk) — Aeonium arboreum var. atropurpureum hort. ex Nichols.']::text[], 'Succulenta arbustiva sempreverde della famiglia delle Crassulacee, dal portamento lasso, che raggiunge 1,5 m di altezza. I fusti legnosi, poco ramificati, portano all''apice rosette di foglie carnose e lucide; in tarda primavera dal centro delle rosette più vecchie si alzano pannocchie coniche di piccoli fiori gialli a stella. Ne esistono forme molto coltivate a foglia porpora scura o variegata.', 'A lax evergreen sub-shrub to 1.5m, with deep red-purple leaves and conical panicles of small yellow flowers in late spring', 'it', '{"luce": "Pieno sole", "acqua": "Ben drenato", "terreno": "Franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetto ad afidi e cocciniglie farinose; Malattie: generalmente esente da malattie', 'Rusticità: minime non sotto i 5 °C', 'Dimensioni a maturità: altezza 1-1.5m, diffusione 1-1.5m', 'Potatura: non richiede potatura; si possono togliere le rosette secche dopo la fioritura', 'Propagazione: per seme in primavera, a 19-24 °C, oppure per talea di rosetta, tenuta a circa 18 °C e appena umida finché non radica']::text[], 'bozza', true, 'succulenta', 'controllo periodico RHS del 19/11/2026, schede nuove; pagina RHS 185690'),
('328a506d-f940-5bda-a993-51241de491fa'::uuid, '04497ebd-3dc2-4642-a72c-59fc8bdfbea1'::uuid, array['RHS (rhs.org.uk) — Agave sobolifera var. serrulata']::text[], 'Grande succulenta perenne della famiglia delle Asparagacee, di solito priva di fusto o con un fusto corto fino a 50 cm, che forma una rosetta larga fino a 2 m di foglie rigide, da lineari a lanceolate, verdi o verde-grigio, con piccoli denti sui margini e una spina all''apice. Le piante adulte alzano un lungo scapo ramificato di piccoli fiori verde-giallo; dopo la fioritura la rosetta principale muore, ma spesso lascia polloni alla base.', 'A large, perennial succulent, usually stemless but sometimes with a short stem to 50cm, forming a rosette up to 2m across of stiff, linear to lance-shaped, green or grey-green leaves, with fine teeth along the edges and spines at the tips. Mature plants produce a tall, branching spike of small yellow-green flowers; the main rosette will die off after flowering, but plants often produce offsets', 'it', '{"luce": "Pieno sole", "acqua": "Ben drenato", "terreno": "Franco, sabbioso; pH acido, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetta a cocciniglie; Malattie: generalmente esente da malattie', 'Rusticità: minime non sotto 1 °C', 'Dimensioni a maturità: altezza 1.5-2.5m, diffusione 1.5-2.5m', 'Potatura: non richiede potatura', 'Propagazione: per seme, oppure staccando i polloni in primavera o in autunno']::text[], 'bozza', true, 'succulenta', 'controllo periodico RHS del 19/11/2026, schede nuove; pagina RHS 250213'),
('60268bdd-b21e-5d2a-bdca-04f2edd147ed'::uuid, '2a24852a-d58f-44b7-bf08-69ef710a816e'::uuid, array['RHS (rhs.org.uk) — Alchemilla velebitica']::text[], 'Piccola perenne cespitosa della famiglia delle Rosacee, alta da 15 a 30 cm, originaria dei monti dei Balcani. Le foglie, verde medio, sono fittamente coperte di peli sericei sulla pagina inferiore e da giovani restano ben piegate lungo la nervatura centrale. In estate porta spruzzi di minuscoli fiori verde-giallo.', 'A clump-forming perennial about 15-30cm in height, the mid-green leaves densely silky-hairy beneath and distinctly folded along the midrib when young. Tiny yellowish-green flowers produced in sprays during summer', 'it', '{"luce": "Pieno sole, mezz''ombra", "acqua": "Umido ma ben drenato", "terreno": "Calcareo, argilloso, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: generalmente esente da parassiti; Malattie: generalmente esente da malattie', 'Rusticità: minime anche sotto i -20 °C', 'Dimensioni a maturità: altezza 0.1-0.5m, diffusione 0.1-0.5m', 'Potatura: dopo la fioritura, in estate, si taglia la pianta per favorire nuove foglie fresche', 'Propagazione: per seme in primavera o per divisione a inizio primavera o in autunno']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 19/11/2026, schede nuove; pagina RHS 516803'),
('8bd3cfef-7d5b-5280-b08f-a2199b650ab0'::uuid, 'f6454a97-f607-4e24-8131-5e1cd8d0e579'::uuid, array['RHS (rhs.org.uk) — Alkekengi officinarum']::text[], 'Perenne erbacea vigorosa della famiglia delle Solanacee, nota come alchechengi, alta fino a 60 cm, con foglie ovate. In estate porta fiori penduli a campana, giallo crema, larghi 2 cm, a cui seguono i caratteristici calici gonfi a lanterna, arancio intenso e lunghi 5 cm, che racchiudono una bacca rossa. Si espande con vigore e va tenuta sotto controllo.', 'A vigorous herbaceous perennial to 60cm tall, with ovate leaves.  Nodding, creamy-yellow bell-shaped flowers 2cm wide appear in summer, followed by inflated, lantern-like deep orange calyces 5cm long, enclosing red berries', 'it', '{"luce": "Pieno sole, mezz''ombra", "acqua": "Ben drenato", "terreno": "Calcareo, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetto ai danni dei bruchi; Malattie: generalmente esente da malattie', 'Rusticità: minime anche sotto i -20 °C', 'Dimensioni a maturità: altezza 0.5-1m, diffusione 0.5-1m', 'Potatura: non richiede potatura', 'Propagazione: per seme in vaso, in cassone freddo, in primavera, oppure per divisione in primavera']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 19/11/2026, schede nuove; pagina RHS 327415'),
('a97bbeb4-8442-5d6d-9dc9-fb911cbd955a'::uuid, '0e7863e8-84bb-4872-bf14-362cd5ac4aec'::uuid, array['RHS (rhs.org.uk) — Allium longispathum']::text[], 'Bulbosa perenne vigorosa della famiglia delle Amaryllidaceae, alta fino a 70 cm, con foglie lineari aromatiche verde medio lunghe fino a 25 cm. In estate porta ombrelle larghe fino a 5 cm, con un massimo di quaranta fiori a campana bianchi, rosa o bruno-giallastri, dagli stami ben sporgenti.', 'Vigorous bulbous perennial to 70cm in height, with aromatic, linear mid-green leaves to 25cm long, and bearing umbels to 5cm across of up to 40 bell-shaped white pink or yellowish-brown flowers with prominent stamens, in summer', 'it', '{"luce": "Pieno sole", "acqua": "Umido ma ben drenato, ben drenato", "terreno": "Calcareo, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetto a minatrice fogliare dell''aglio e mosca della cipolla; Malattie: può essere soggetto a marciume bianco della cipolla e peronospora', 'Rusticità: minime fino a -20 °C', 'Dimensioni a maturità: altezza 0.5-1m, diffusione 0.1-0.5m', 'Potatura: non richiede potatura, salvo la rimozione degli steli fioriti e del fogliame vecchio', 'Propagazione: per seme appena maturo o in primavera, oppure per bulbilli, da staccare con cura sollevando il bulbo a fioritura terminata']::text[], 'bozza', true, 'bulbosa', 'controllo periodico RHS del 19/11/2026, schede nuove; pagina RHS 186189'),
('7163087d-f8dc-5583-8314-16a465ed9d34'::uuid, 'cd2e45be-d28a-453b-af61-3d9b9208c5dd'::uuid, array['RHS (rhs.org.uk) — Datura suaveolens']::text[], 'Arbusto della famiglia delle Solanacee, semisempreverde e sensibile al freddo, alto fino a 2,5 m. In estate e in autunno porta grandi fiori bianchi a tromba, penduli, che la sera spandono un profumo intenso. Nelle zone dagli inverni freddi si coltiva in vaso, all''aperto dopo le ultime gelate e al riparo durante l''inverno, con minime di 7-10 °C; si può allevare anche ad alberello.', 'A tender shrub with semi-evergreen leaves. It bears large, hanging, white trumpet-shaped flowers in summer and autumn. These are night-scented', 'it', '{"luce": "Pieno sole", "acqua": "Umido ma ben drenato", "terreno": "Franco; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: al riparo può essere soggetta a ragnetto rosso, mosca bianca, tripidi e cocciniglie farinose; Malattie: generalmente esente da malattie', 'Rusticità: minime non sotto i 5 °C', 'Dimensioni a maturità: altezza 1.5-2.5m, diffusione 1.5-2.5m', 'Potatura: quando la pianta si ritira al riparo in autunno si possono accorciare con decisione i rami', 'Propagazione: per seme o per talee erbacee o semilegnose']::text[], 'bozza', true, 'arbusto', 'controllo periodico RHS del 19/11/2026, schede nuove; pagina RHS 5356'),
('1e792f71-411e-5f60-a2db-38dc1d33189c'::uuid, 'cabe52ec-bbf5-4b84-8627-e0568d098ae7'::uuid, array['RHS (rhs.org.uk) — Campanula isophylla f. alba']::text[], 'Perenne della famiglia delle Campanulacee, alta circa 20 cm, originaria delle rupi calcaree della Liguria, con fusti ricadenti che portano foglie a cuore. In estate si copre di fiori stellati larghi 3,5 cm, azzurri o, nella forma alba, bianchi puri. Teme il freddo intenso e si coltiva volentieri in vaso o in cestino appeso.', 'A rather tender perennial to 20cm tall, with trailing stems bearing heart-shaped leaves and star-shaped pure white flowers 3.5cm across in summer', 'it', '{"luce": "Pieno sole, mezz''ombra", "acqua": "Ben drenato", "terreno": "Franco; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: al riparo può essere soggetta a ragnetto rosso, afidi e oziorrinco; Malattie: può soffrire di oidio', 'Rusticità: minime non sotto 1 °C', 'Dimensioni a maturità: altezza 0.1-0.5m, diffusione 0.1-0.5m', 'Potatura: prima dell''inverno si tagliano alla base i fusti secchi', 'Propagazione: per talee erbacee a inizio primavera, con calore dal basso']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 19/11/2026, schede nuove; pagina RHS 28683'),
('1d4453df-b7f1-5dc1-bd24-1950dd171cca'::uuid, 'd34fc5db-5657-4120-bbb7-8d0d74a938d9'::uuid, array['RHS (rhs.org.uk) — Chamaecytisus hirsutus var. demissus']::text[], 'Arbusto caducifoglio della famiglia delle Fabacee, a crescita lenta, che nelle forme più basse resta un tappeto alto meno di 10 cm e largo 20. Le foglie, composte da foglioline verde medio, sono sericee e pelose sulla pagina inferiore. Tra fine primavera e inizio estate porta mazzetti di fiori gialli con la carena bruna.', 'Slow-growing, mat-forming, deciduous shrub to 8cm tall and 20cm wide with mid-green leaves, silky-hairy beneath and composed of leaflets; bears clusters of yellow flowers with brown keels and bracts, in late spring and early summer', 'it', '{"luce": "Pieno sole", "acqua": "Ben drenato", "terreno": "Franco, sabbioso; pH acido, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetto all''eriofide delle ginestre; Malattie: può essere soggetto ad armillaria', 'Rusticità: minime fino a -15 °C', 'Dimensioni a maturità: altezza fino a 0.1m, diffusione 0.1-0.5m', 'Potatura: dopo la fioritura si accorciano i rami che hanno fiorito, senza mai tagliare nel legno vecchio, che non ributta', 'Propagazione: per talee semilegnose a fine estate']::text[], 'bozza', true, 'arbusto', 'controllo periodico RHS del 19/11/2026, schede nuove; pagina RHS 105679'),
('78b5e4b5-cf85-50c0-a4e4-67f90814a7de'::uuid, 'a581c6c0-16de-4e3d-a392-921008e9d532'::uuid, array['RHS (rhs.org.uk) — Clavija ornata']::text[], 'Alberello tropicale sempreverde della famiglia delle Primulacee, poco ramificato, con un tronco alto circa 4 m che porta in cima lunghe foglie lanceolate verdi, così da ricordare una palma. Piccoli fiori arancioni spuntano su racemi sottili direttamente dal tronco; seguono frutti commestibili arancio vivo, grandi come una pallina da golf. Nei nostri climi si coltiva in serra, in giardino d''inverno o come pianta d''appartamento.', 'A sparsely branching, tropical, evergreen tree, with a trunk to about 4m (13ft) high on which long lance-shaped green leaves are borne, producing a palm-like appearance. Small orange flowers are produced on slender racemes directly from the trunk and followed by golf-ball sized, bright orange, edible fruit.', 'it', '{"luce": "Pieno sole, mezz''ombra", "acqua": "Umido ma ben drenato, ben drenato", "terreno": "Franco, sabbioso; pH acido, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetta a ragnetto rosso, cocciniglie e cocciniglie farinose; Malattie: generalmente esente da malattie', 'Rusticità: minime non sotto i 10 °C', 'Dimensioni a maturità: altezza 2.5-4m, diffusione 1.5-2.5m', 'Potatura: richiede pochissima potatura: si tolgono solo i rami secchi o rovinati', 'Propagazione: per seme']::text[], 'bozza', true, 'albero', 'controllo periodico RHS del 19/11/2026, schede nuove; pagina RHS 213021'),
('12817386-5f95-5bcf-bdeb-a1a0cc890bb4'::uuid, 'fa56dc21-4ab5-45cc-9d80-0fe7c84bd42f'::uuid, array['RHS (rhs.org.uk) — Clinopodium calamintha']::text[], 'Perenne compatta e cespugliosa della famiglia delle Lamiacee, alta fino a 60 cm, con foglie ovate verde-grigio dal profumo di menta. Dall''estate all''inizio dell''autunno porta mazzetti radi di minuscoli fiori tubolari bilabiati, bianchi o lilla pallido, lunghi fino a 1 cm. Le foglie si usano in cucina.', 'A compact, bushy perennial, to 60cm tall, with aromatic, ovate grey-green leaves. Loose clusters of tiny, up to 1cm, tubular, two-lipped white or pale lilac flowers appear from summer into early autumn', 'it', '{"luce": "Pieno sole", "acqua": "Ben drenato", "terreno": "Calcareo, franco, sabbioso; pH alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: generalmente esente da parassiti; Malattie: può soffrire di oidio', 'Rusticità: minime fino a -15 °C', 'Dimensioni a maturità: altezza 0.5-1m, diffusione 0.5-1m', 'Potatura: si taglia in autunno', 'Propagazione: per seme o per divisione']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 19/11/2026, schede nuove; pagina RHS 97329'),
('8305e563-2788-5af2-a017-634aac089df9'::uuid, '91af781c-6eab-4f25-b7ef-dd2a8e8e1fcb'::uuid, array['RHS (rhs.org.uk) — Clivia miniata yellow-flowered']::text[], 'Perenne sempreverde della famiglia delle Amaryllidaceae, originaria del Sudafrica, con foglie a nastro verde scuro disposte a ventaglio. In primavera e in estate alza robusti steli con ombrelle di fiori a tromba lunghi fino a 7 cm, di solito arancioni con la gola gialla, in alcune forme giallo limone. Fiorisce meglio con le radici un po'' strette nel vaso.', 'An evergreen perennial with strap-shaped leaves and umbels of light lemon-yellow, trumpet-shaped flowers to 7cm long in spring and summer', 'it', '{"luce": "Pieno sole, mezz''ombra", "acqua": "Ben drenato", "terreno": "Calcareo, argilloso, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetta a cocciniglie farinose; Malattie: generalmente esente da malattie', 'Rusticità: minime non sotto i 5 °C', 'Dimensioni a maturità: altezza 0.1-0.5m, diffusione 0.1-0.5m', 'Potatura: non richiede potatura', 'Propagazione: per seme appena maturo, a 16-21 °C, o per divisione a fine inverno o a inizio primavera']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 19/11/2026, schede nuove; pagina RHS 171979'),
('bcda970c-9ddf-5cd3-8b72-70a157191e92'::uuid, '2d41b267-5b30-4eee-b4d6-c0d0c319f373'::uuid, array['RHS (rhs.org.uk) — Crocus salzmannii']::text[], 'Croco a fioritura autunnale della famiglia delle Iridacee, alto fino a 10 cm. I fiori a imbuto, lilla azzurro e talvolta con la gola gialla, spuntano insieme alle foglie strette e lineari. Durante il riposo vuole un terreno caldo e asciutto.', 'An autumn-flowering corm. Funnel-shaped, lilac blue flowers, to 10cm in height, sometimes with a yellow throat, appear with the narrow, linear leaves', 'it', '{"luce": "Pieno sole", "acqua": "Ben drenato", "terreno": "Franco, sabbioso; pH neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetto ai danni di roditori e uccelli; Malattie: generalmente esente da malattie, ma i cormi possono marcire durante la conservazione', 'Rusticità: minime fino a -20 °C', 'Dimensioni a maturità: altezza fino a 0.1m, diffusione 0-0.1m', 'Potatura: non richiede potatura', 'Propagazione: per seme o per divisione dei cespi']::text[], 'bozza', true, 'bulbosa', 'controllo periodico RHS del 19/11/2026, schede nuove; pagina RHS 29619'),
('611d9723-b6b5-5b0f-8b4b-129bbc0db9e0'::uuid, 'fbf54553-0fc8-4461-941d-d1fa9756a368'::uuid, array['RHS (rhs.org.uk) — Cyclamen latifolium']::text[], 'Pianta tuberosa della famiglia delle Primulacee, originaria del Mediterraneo orientale, alta da 10 a 20 cm. Le foglie a cuore, verde scuro, sono marmorizzate d''argento; in inverno o in primavera porta fiori profumati bianchi o rosa, con i petali rivolti all''insù e la bocca carminio. È il ciclamino da appartamento, da cui derivano numerose varietà dai colori più vivi.', 'A winter or spring-flowering tuber, growing to 10-20cm in height. Heart-shaped, dark-green leaves have silver markings. Fragrant white or pink flowers with petals swept upwards have carmine mouths', 'it', '{"luce": "Pieno sole, mezz''ombra", "acqua": "Ben drenato", "terreno": "Franco; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetto a topi e scoiattoli, e all''oziorrinco quando è coltivato in vaso; Malattie: può soffrire di muffa grigia e di marciume nero delle radici', 'Rusticità: minime non sotto i 5 °C', 'Dimensioni a maturità: altezza 0.1-0.5m, diffusione 0.1-0.5m', 'Potatura: non richiede potatura', 'Propagazione: per seme appena maturo, al buio, a 12-15 °C; può aiutare tenere i semi in acqua per dieci ore prima della semina']::text[], 'bozza', true, 'bulbosa', 'controllo periodico RHS del 19/11/2026, schede nuove; pagina RHS 78756'),
('c5d889ac-d255-53a9-9ffb-9cff3e294475'::uuid, 'f900cad5-1161-4078-9802-7d7792b1505f'::uuid, array['RHS (rhs.org.uk) — Dendrobium × speciokingianum pink']::text[], 'Orchidea epifita semisempreverde della famiglia delle Orchidacee, ibrido naturale australiano, con lunghi pseudobulbi carnosi a canna, verdi e avvolti da guaine argentee. Verso la cima di ogni pseudobulbo si alternano da due a cinque foglie lanceolate, coriacee, verde scuro, lunghe 7-17 cm. Dalle ascelle delle canne adulte escono steli lunghi fino a 30 cm con grappoli di piccoli fiori profumati, bianchi o rosa.', 'An epiphytic, semi-evergreen orchid with long, cane-like, fleshy, green pseudobulbs, covered with thin, silvery sheaths. Two to five, dark green, thick, leathery leaves are alternately arranged near the top of each pseudobulb. Each lance-shaped leaf is 7-17cm long, and 3cm wide. Flowering stems up to 30cm long emerge from the axils of leaves on mature canes and carry clusters of white, 1cm small, fragrant flowers.', 'it', '{"luce": "Pieno sole, mezz''ombra", "acqua": "Ben drenato", "terreno": "pH neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetta a cocciniglie, afidi, cocciniglie farinose e ragnetto rosso; Malattie: generalmente esente da malattie', 'Rusticità: minime non sotto i 5 °C', 'Dimensioni a maturità: altezza 0.5-1m, diffusione 0.5-1m', 'Potatura: non richiede potatura; si tolgono i fiori appassiti e si elimina una canna solo quando è del tutto avvizzita, lasciando sempre almeno tre canne giovani con le foglie', 'Propagazione: dividendo le piante adulte quando riempiono il vaso, oppure staccando i getti laterali (keiki) sulle canne vecchie quando le radici sono lunghe almeno 2 cm; il seme si fa germinare solo in laboratorio']::text[], 'bozza', true, 'orchidea', 'controllo periodico RHS del 19/11/2026, schede nuove; pagina RHS 165742'),
('4477dcf2-9ca4-51ae-a509-8a0e6f4f1273'::uuid, '2d2c3eb8-1fc2-45bc-bb30-e9cf13c38e43'::uuid, array['RHS (rhs.org.uk) — Fittonia argyroneura']::text[], 'Perenne sempreverde strisciante della famiglia delle Acantacee, originaria del Perù, con fusti che radicano a contatto col terreno. Le foglie, ampie ed ellittiche, verde intenso, sono percorse da un fitto reticolo di venature argentee o rosate; i fiori, bianchi, sono piccoli e poco appariscenti. Si coltiva come pianta d''appartamento.', 'A creeping evergreen perennial with rooting stems and broadly elliptic, rich green leaves with an attractive tracery of silvery veins and insignificant white flowers', 'it', '{"luce": "Mezz''ombra", "acqua": "Umido ma ben drenato", "terreno": "Franco, sabbioso; pH neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetta a ragnetto rosso e cocciniglie farinose; Malattie: può soffrire di muffa grigia', 'Rusticità: minime non sotto i 15 °C', 'Dimensioni a maturità: altezza 0.1-0.5m, diffusione 0.1-0.5m', 'Potatura: non richiede potatura', 'Propagazione: per talee apicali con tre o quattro paia di foglie in primavera, o per propaggine in primavera o in estate']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 19/11/2026, schede nuove; pagina RHS 7229'),
('abc2fd1f-2a98-5baa-ab77-cfe478d5147a'::uuid, 'bf4f5f44-d15a-4240-95ec-e91cdd540af2'::uuid, array['RHS (rhs.org.uk) — Francoa appendiculata var. sonchifolia Rogerson''s form']::text[], 'Perenne sempreverde della famiglia delle Francoacee, originaria del Cile, alta fino a 60 cm, con una rosetta basale di foglie lanceolate, lobate e morbidamente pelose. In estate alza spighe di fiori viola pallido con i petali striati di porpora più scuro.', 'An evergreen perennial to 60cm high, with a basal rosette of broadly lance-shaped, lobed, softly hairy green leaves. Spikes of pale purple flowers, with petals streaked with darker purple, are borne in summer', 'it', '{"luce": "Pieno sole, mezz''ombra", "acqua": "Umido ma ben drenato", "terreno": "Calcareo, argilloso, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: generalmente esente da parassiti; Malattie: generalmente esente da malattie', 'Rusticità: minime fino a -10 °C', 'Dimensioni a maturità: altezza 0.5-1m, diffusione 0.1-0.5m', 'Potatura: non richiede potatura', 'Propagazione: per divisione in primavera']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 19/11/2026, schede nuove; pagina RHS 544838'),
('7630eaee-7b5e-54c4-a0a5-c47b29fdbf68'::uuid, '5aaf816c-bf02-46e7-a4cf-f0f57e49d2ae'::uuid, array['RHS (rhs.org.uk) — Gardenia grandiflora']::text[], 'Arbusto sempreverde della famiglia delle Rubiacee, originario dell''Asia orientale, alto fino a 1,5 m, con foglie ellittiche verde scuro e lucide. In estate e in autunno porta fiori bianchi a imbuto, larghi 8 cm, dal profumo intensissimo. Vuole terreno senza calcare e teme il freddo: sotto i 6 °C circa va portata al riparo.', 'A large evergreen shrub with deep glossy green, elliptic leaves and very fragrant, broadly funnel-shaped white flowers 8cm across in summer and autumn', 'it', '{"luce": "Mezz''ombra", "acqua": "Umido ma ben drenato", "terreno": "Argilloso, franco, sabbioso; pH acido, neutro"}'::jsonb, 'perenne', array['Parassiti: al riparo può essere soggetta a mosca bianca e cocciniglie farinose; Malattie: al riparo può soffrire di muffa grigia', 'Rusticità: minime non sotto i 5 °C', 'Dimensioni a maturità: altezza 1-1.5m, diffusione 1-1.5m', 'Potatura: dopo la fioritura si accorciano leggermente i rami per mantenere la forma e si tolgono quelli secchi', 'Propagazione: per seme, per talee erbacee o semilegnose']::text[], 'bozza', true, 'arbusto', 'controllo periodico RHS del 19/11/2026, schede nuove; pagina RHS 33348'),
('b1f4064d-2e82-5228-9ca6-f7a497908386'::uuid, 'ff4f1ea4-8a55-40d9-abf7-4592d36087de'::uuid, array['RHS (rhs.org.uk) — Gazania splendens']::text[], 'Perenne sempreverde della famiglia delle Asteracee, originaria del Sudafrica, bassa ed espansa, spesso coltivata come annuale. Le foglie lanceolate sono verde-grigio; da fine primavera a inizio estate, e più a lungo dove il clima è mite, porta fiori a margherita dai colori accesi, soprattutto gialli e arancioni, che si aprono al sole e si chiudono col cielo coperto.', 'A spreading, low-growing evergreen herbaceous perennial, usually grown as an annual, with lance-shaped blue-grey foliage and daisy-like brightly-coloured flowers in mainly yellow or orange shades, which appear from late spring to early summer, longer in milder climates.  The flowers open in the sun and close when cloudy or dark', 'it', '{"luce": "Pieno sole", "acqua": "Umido ma ben drenato, ben drenato", "terreno": "Franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: generalmente esente da parassiti, salvo gli afidi quando sverna al chiuso; Malattie: generalmente esente da malattie, ma al chiuso può soffrire di muffa grigia', 'Rusticità: minime non sotto 1 °C', 'Dimensioni a maturità: altezza 0.1-0.5m, diffusione 0.1-0.5m', 'Potatura: non richiede potatura; si tolgono spesso i fiori appassiti', 'Propagazione: per talee erbacee prese alla base dei getti a fine estate, da tenere al riparo dal gelo durante l''inverno']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 19/11/2026, schede nuove; pagina RHS 33386'),
('d0d5079b-b686-56c4-bf7e-c3585f190049'::uuid, 'c50023a0-2b0f-4578-afda-3dc753840cec'::uuid, array['RHS (rhs.org.uk) — Hoya carnosa var. compacta']::text[], 'Rampicante sempreverde semisucculento della famiglia delle Apocinacee, a crescita lenta, nota come fior di cera, con foglie opposte, carnose e rigide, verde scuro. Dalla primavera all''autunno porta infiorescenze a cupola di fiori cerosi a stella, profumati, con il centro rosso. Non ama i rinvasi e può restare per molti anni nello stesso vaso.', 'A slow-growing, semi-succulent, evergreen vine bearing opposite pairs of puckered, rigid, dark green leaves. From spring to autumn it produces domed clusters of fragrant, waxy, star-shaped flowers with red centres', 'it', '{"luce": "Pieno sole, mezz''ombra", "acqua": "Ben drenato", "terreno": "Franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetta a cocciniglie farinose; Malattie: generalmente esente da malattie', 'Rusticità: minime non sotto 1 °C', 'Dimensioni a maturità: altezza 0.5-1m, diffusione 0.1-0.5m', 'Potatura: non ha bisogno di potature regolari; dopo la fioritura si accorciano i rami che escono dallo spazio a disposizione, lasciando sulla pianta i peduncoli dei fiori, da cui rifiorisce', 'Propagazione: per propaggine in primavera o in estate, oppure per talee semilegnose con calore dal basso a fine estate']::text[], 'bozza', true, 'rampicante', 'controllo periodico RHS del 19/11/2026, schede nuove; pagina RHS 130978'),
('1a917cb1-f089-5c04-9e51-ac10bd4b3caa'::uuid, 'e31c9865-a817-4c85-868d-5a750ca12890'::uuid, array['RHS (rhs.org.uk) — Impatiens sultani']::text[], 'Perenne erbacea della famiglia delle Balsaminacee, originaria dell''Africa orientale, dal Kenya al Mozambico, e coltivata quasi sempre come annuale da aiuola: è la comune balsamina o begliuomini. Alta da 15 a 60 cm, ha fusti e foglie semisucculenti, teneri e fragili, e foglie lanceolate verdi, talvolta rossastre sotto. Fiorisce con grande generosità per tutta l''estate, con fiori a cinque petali larghi 2-5 cm e uno sperone di 1 cm; ama la mezz''ombra ma regge il sole se il terreno resta umido.', 'Also commonly known as ''Busy Lizzie'', ''Balsam'', or simply ''Impatiens'', this is a species of the genus Impatiens, native to eastern Africa from Kenya to Mozambique. It is a tender herbaceous perennial plant but mostly grown as annual bedding. It grows approximately 15–60 cm tall, with broad lanceolate leaves 3–12 cm long and 2–5 cm broad. Leaves are mostly alternate, although they may be opposite near the top of the plant. The changeable, simple leaves are stalked and 1.5 to 6 cm long, green and sometimes spotted, pinkish or reddish on the underside. It''s a very floriferous plant with blooms 2–5 cm diameter, with five petals and a 1 cm spur. The leaves and stems are semi-succulent, and all parts of the plant (leaves, stems, flowers, roots) are rather soft and easily damaged. A very useful summer bedding plant for more shady locations in the garden that will also thrive in full sun if kept moist and well watered.', 'it', '{"luce": "Ombra piena, pieno sole, mezz''ombra", "acqua": "Umido ma ben drenato", "terreno": "Calcareo, argilloso, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: generalmente esente da parassiti, ma può essere soggetta ad afidi, ragnetto rosso e oziorrinco; Malattie: può soffrire di peronospora', 'Rusticità: minime non sotto i 10 °C', 'Dimensioni a maturità: altezza 0.1-0.5m, diffusione 0.1-0.5m', 'Potatura: da giovane si cima l''apice per avere una pianta ben ramificata; togliendo con regolarità i fiori appassiti la fioritura si prolunga fino all''autunno', 'Propagazione: per seme o per talee erbacee']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 19/11/2026, schede nuove; pagina RHS 110933'),
('76307a67-2993-5852-aaf7-6fa92a4eed9e'::uuid, 'dd86bc72-1075-4fcd-b8dd-9eb5b7b3f2a1'::uuid, array['RHS (rhs.org.uk) — Iris attica subsp. pumila']::text[], 'Piccolo iris barbato rizomatoso della famiglia delle Iridacee, originario della Grecia e dei Balcani, alto fino a 15 cm, con foglie a spada leggermente glauche. A metà primavera ogni stelo porta uno o due fiori a tubo lungo, larghi 2,5-5 cm, di colore molto variabile, dal viola porpora al blu, al giallo o al bianco, quasi sempre con macchie più scure sui petali esterni e la barba gialla o blu.', 'A compact, rhizomatous, bearded iris to 15cm tall with slightly glaucous, widely sword-shaped leaves 3-15cm long. In mid-spring, a 1cm long flower stem bears 1-2, long-tubed flowers, each 2.5-5cm wide. Flowers are variable in colour from violet-purple, blue to yellow or white with most having a darker spot pattern on the falls and yellow or blue beards', 'it', '{"luce": "Pieno sole", "acqua": "Ben drenato", "terreno": "Calcareo, franco, sabbioso; pH alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetto a lumache, chiocciole e tripidi; Malattie: può soffrire di virosi trasmesse dagli afidi, marciume batterico molle e muffa grigia', 'Rusticità: minime anche sotto i -20 °C', 'Dimensioni a maturità: altezza 0.1-0.5m, diffusione 0.5-1m', 'Potatura: dopo la fioritura si tagliano gli steli sfioriti e in autunno si tolgono le foglie che seccano', 'Propagazione: per seme o per divisione dei rizomi dopo la fioritura, da metà a fine estate']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 19/11/2026, schede nuove; pagina RHS 183260'),
('5f06251a-e23f-51d4-aecf-91d45f0268ee'::uuid, 'abd2fe15-a7f8-48a9-9770-750928518079'::uuid, array['RHS (rhs.org.uk) — Iris halophila']::text[], 'Iris rizomatoso della famiglia delle Iridacee, originario delle steppe dell''Asia centrale, alto fino a 90 cm, con foglie strette ed erette lunghe fino a 30 cm. In estate gli steli ramificati portano fiori larghi fino a 8 cm, bianchi o da giallo pallido a giallo scuro, venati di tinte più cupe.', 'A tall rhizomatous perennial, reaching up to 90cm high, with narrow, upright leaves to 30cm long. Flowers, borne in summer on branched stems, are coloured white and pale to dark yellow with darker veining and reach up to 8cm in diameter', 'it', '{"luce": "Pieno sole, mezz''ombra", "acqua": "Umido ma ben drenato", "terreno": "Argilloso, franco, sabbioso; pH acido, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetto a lumache, chiocciole e tripidi; Malattie: può soffrire di virosi trasmesse dagli afidi, marciume batterico molle e muffa grigia', 'Rusticità: minime fino a -20 °C', 'Dimensioni a maturità: altezza 0.5-1m, diffusione 0.1-0.5m', 'Potatura: in autunno si tolgono le foglie che seccano; gli steli sfioriti si possono tagliare dopo la fioritura', 'Propagazione: per seme o per divisione']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 19/11/2026, schede nuove; pagina RHS 92900'),
('8971e2ba-053f-58f4-8e63-0cffaa9d865a'::uuid, '006a484b-7851-423f-9063-f7ec5a97fce8'::uuid, array['RHS (rhs.org.uk) — Jacobinia carnea']::text[], 'Arbusto tropicale sempreverde della famiglia delle Acantacee, originario del Brasile, eretto e alto fino a 2 m nelle condizioni adatte, con foglie lussureggianti verde scuro, porpora sulla pagina inferiore. Da metà estate porta in abbondanza pennacchi di fiori rosa vivo. Non sopporta il gelo e d''inverno va tenuto in un luogo fresco e luminoso.', 'An upright, tender evergreen tropical shrub, reaching 2m in height in the right growing conditions, with lush, dark green foliage, purple on the undersides.  Plumes of bright pink flowers appear in abundance from mid-summer onwards.  A lush and colourful shrub for giving your garden a tropical feel', 'it', '{"luce": "Pieno sole, mezz''ombra", "acqua": "Umido ma ben drenato, ben drenato", "terreno": "Franco; pH acido, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetta a ragnetto rosso e mosca bianca; Malattie: generalmente esente da malattie, ma con l''aria molto secca le foglie possono deformarsi', 'Rusticità: minime non sotto 1 °C', 'Dimensioni a maturità: altezza 1.5-2.5m, diffusione 0.5-1m', 'Potatura: a inizio primavera, prima della ripresa, si spunta leggermente; durante la stagione si tolgono le foglie secche o ingiallite e le piante vecchie o trascurate si possono ringiovanire con un taglio deciso in primavera', 'Propagazione: per talee semilegnose in primavera o a inizio estate']::text[], 'bozza', true, 'arbusto', 'controllo periodico RHS del 19/11/2026, schede nuove; pagina RHS 9430'),
('1bbab6b7-a41e-59e6-ba0f-b75e91b12940'::uuid, 'a9753ea9-c937-443d-8b6c-4ccea65eee9b'::uuid, array['RHS (rhs.org.uk) — Lewisia cotyledon [Elise Mixed]']::text[], 'Perenne sempreverde cespitosa della famiglia delle Montiacee, originaria dei monti della California e dell''Oregon, con rosette carnose di foglie verde scuro. Dalla primavera all''estate fiorisce a lungo, con fiori rosa, arancioni, gialli o bianchi, tanto più se si tolgono quelli appassiti. È adatta al giardino roccioso e alle fessure dei muretti a secco, e teme l''umidità invernale.', 'A clump-forming perennial, with fleshy rosettes of dark green leaves. Flowers prolifically for a long period if deadheaded regularly from spring to summer. Flowers range from pink, orange, yellow and white.', 'it', '{"luce": "Mezz''ombra", "acqua": "Ben drenato", "terreno": "Franco, sabbioso; pH acido, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetta ad afidi, lumache e chiocciole; Malattie: può marcire nei terreni troppo umidi', 'Rusticità: minime fino a -10 °C', 'Dimensioni a maturità: altezza 0.1-0.5m, diffusione 0.1-0.5m', 'Potatura: si tolgono i fiori appassiti', 'Propagazione: staccando le rosette laterali a inizio estate']::text[], 'bozza', true, 'succulenta', 'controllo periodico RHS del 19/11/2026, schede nuove; pagina RHS 351319'),
('e0310495-676c-5456-8dbe-37654e6177bd'::uuid, '3003dfd6-ede6-4454-9e55-f36e7491aa31'::uuid, array['RHS (rhs.org.uk) — Neoregelia carolinae var. tricolor']::text[], 'Bromeliacea perenne e sempreverde originaria del Brasile, che forma una rosetta di foglie a nastro lunghe fino a 45 cm; al momento della fioritura il centro della rosetta si tinge di rosso cremisi, dove spuntano piccoli fiori viola. Nella varietà tricolor le foglie sono anche striate di bianco e di verde. Va annaffiata con acqua dolce, versandola anche nel cuore della rosetta.', 'A perennial forming an evergreen rosette of strap-shaped leaves to 45cm in length, striped with white and green, and suffused with crimson at the base. Violet flowers with red bracts appear in the centre', 'it', '{"luce": "Mezz''ombra", "acqua": "Umido ma ben drenato", "terreno": "Franco; pH neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetta a cocciniglie; Malattie: generalmente esente da malattie', 'Rusticità: minime non sotto i 10 °C', 'Dimensioni a maturità: altezza 0.1-0.5m, diffusione 0.1-0.5m', 'Potatura: si tagliano alla base le rosette che hanno fiorito', 'Propagazione: per seme appena maturo, a 27 °C, o staccando i getti laterali in primavera o in estate']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 19/11/2026, schede nuove; pagina RHS 187899'),
('810ba7e8-e801-57c7-afe5-e885963c088b'::uuid, '113e4bc9-5321-40af-acee-565925b3d8d2'::uuid, array['RHS (rhs.org.uk) — Potentilla argyrophylla']::text[], 'Perenne semisempreverde della famiglia delle Rosacee, originaria dell''Himalaya, alta fino a 50 cm. Le foglie ordinate, con cinque foglioline verdi, sono coperte di peli argentei che sembrano disegnare un margine bianco. Per tutta l''estate e fino all''inizio dell''autunno porta fiori gialli a cinque petali con la base arancione.', 'A semi-evergreen perennial reaching 50cm. It has neat 5-leaflet green leaves with silver hairs giving the appearance of a white margin. Yellow 5-petalled flowers with orange bases, grow all summer into early autumn', 'it', '{"luce": "Pieno sole", "acqua": "Umido ma ben drenato", "terreno": "Calcareo, argilloso, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: generalmente esente da parassiti; Malattie: può essere soggetta ad armillaria', 'Rusticità: minime fino a -20 °C', 'Dimensioni a maturità: altezza 0.1-0.5m, diffusione 0.1-0.5m', 'Potatura: non richiede potatura', 'Propagazione: per seme o per divisione']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 19/11/2026, schede nuove; pagina RHS 13556'),
('174bd0fc-1a2f-566c-929a-200d2f5e8eec'::uuid, '37398db8-70b3-48a4-97ba-4b60fc8e3582'::uuid, array['RHS (rhs.org.uk) — Pseudofumaria alba']::text[], 'Perenne sempreverde compatta e cespitosa della famiglia delle Papaveracee, originaria dei Balcani, alta fino a 30 cm, con foglie divise in foglioline ovali verde chiaro, più pallide sotto. Da fine primavera all''estate porta fitti grappoli di fiori bianchi con la punta giallo vivo, lunghi fino a 1,5 cm.', 'A compact, clump-forming, evergreen perennial to 30cm tall with foliage divided into oval light green leaflets that are paler beneath. Dense clusters of white flowers tipped with bright yellow, each up to 1.5cm long, are borne from late spring into summer', 'it', '{"luce": "Pieno sole, mezz''ombra", "acqua": "Umido ma ben drenato, ben drenato", "terreno": "Calcareo, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: possono darle fastidio lumache e chiocciole; Malattie: generalmente esente da malattie', 'Rusticità: minime fino a -15 °C', 'Dimensioni a maturità: altezza 0.1-0.5m, diffusione 0.1-0.5m', 'Potatura: non richiede potatura', 'Propagazione: per seme o per divisione']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 19/11/2026, schede nuove; pagina RHS 71488'),
('a4a5aa9d-233e-59f0-aa51-041de82f9fd8'::uuid, '35c48318-3871-4a58-b56f-40a370e7a484'::uuid, array['RHS (rhs.org.uk) — Sedum crassularia']::text[], 'Succulenta sempreverde della famiglia delle Crassulacee, a crescita lenta e più rustica di quanto ci si aspetterebbe, che forma cuscini bassi ed espansi di rosette di foglie carnose e piatte, verde-grigio, spesso sfumate di rosso. In estate porta su steli corti piccoli mazzetti di fiori minuscoli, dal bianco al rosa, che in coltivazione si vedono però di rado. È adatta ai giardini verticali.', 'A surprisingly hardy, slow-growing, evergreen succulent, forming low, spreading cushions of rosettes of fleshy, flat, sometimes recurved grey-green leaves often flushed with red. Clusters of tiny white to pink flowers are produced on short stems in summer, though these are rarely seen in cultivation.  Well-suited for use in living walls', 'it', '{"luce": "Pieno sole", "acqua": "Ben drenato", "terreno": "Franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetto a cocciniglie farinose, oziorrinco e afidi; Malattie: generalmente esente da malattie', 'Rusticità: minime fino a -10 °C', 'Dimensioni a maturità: altezza fino a 0.1m, diffusione 0.1-0.5m', 'Potatura: non richiede potatura', 'Propagazione: per talee di fusto o di foglia']::text[], 'bozza', true, 'succulenta', 'controllo periodico RHS del 19/11/2026, schede nuove; pagina RHS 85467'),
('c266609b-5b96-5686-bf19-0e2f2af1694b'::uuid, '3b5582bc-b452-4046-8f99-d3e09cae1c7b'::uuid, array['RHS (rhs.org.uk) — Marsdenia floribunda']::text[], 'Rampicante volubile sempreverde della famiglia delle Apocinacee, originario del Madagascar, che può superare i 5 m, con foglie coriacee da oblunghe a ellittiche. All''ascella delle foglie porta mazzetti di fiori bianchi profumatissimi, con il tubo sottile lungo fino a 5 cm e i lobi aperti; i frutti sono oblunghi e verdi. Si coltiva quasi sempre come pianta d''appartamento, con un sostegno per i fusti.', 'A twining evergreen climber to 5m or more, with leathery, oblong to elliptic leaves and axillary clusters of highly fragrant, slender-tubed white flowers to 5cm in length, with spreading lobes; fruit oblong, green', 'it', '{"luce": "Pieno sole", "acqua": "Umido ma ben drenato, ben drenato", "terreno": "Calcareo, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetta a cocciniglie, ragnetto rosso e cocciniglie farinose, anche delle radici; Malattie: generalmente esente da malattie', 'Rusticità: minime non sotto i 10 °C', 'Dimensioni a maturità: altezza 4-8m, diffusione 1-1.5m', 'Potatura: non ha bisogno di potature regolari; dopo la fioritura si accorciano i rami che escono dallo spazio a disposizione', 'Propagazione: per seme in primavera, a 18-21 °C, o per talee semilegnose in estate, con calore dal basso']::text[], 'bozza', true, 'rampicante', 'controllo periodico RHS del 19/11/2026, schede nuove; pagina RHS 141792'),
('550c7faa-a4b8-595e-bcd6-e76ce401e395'::uuid, '1e944339-02ab-46cf-ba88-460c9affd666'::uuid, array['RHS (rhs.org.uk) — Thunbergia alata red-orange']::text[], 'Rampicante perenne sempreverde della famiglia delle Acantacee, originaria dell''Africa orientale, a crescita rapida e sensibile al freddo, per questo coltivata spesso come annuale. Le foglie sono a cuore, verdi; in estate e in autunno porta fiori arancioni o gialli con il centro scuro, da cui il nome di Susanna dagli occhi neri. Ha bisogno di un sostegno su cui arrampicarsi.', 'A fast-growing, tender evergreen perennial climber, often grown as an annual, with green heart shaped leaves. Dark orange flowers with a red centres appear in summer and autumn', 'it', '{"luce": "Pieno sole", "acqua": "Umido ma ben drenato, ben drenato", "terreno": "Calcareo, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetta ad afidi e, al riparo, a ragnetto rosso e mosca bianca; Malattie: può soffrire di oidio', 'Rusticità: minime non sotto 1 °C', 'Dimensioni a maturità: altezza 1.5-2.5m, diffusione 0.5-1m', 'Potatura: richiede poca potatura: si accorciano i fusti che escono dallo spazio a disposizione e si tolgono spesso i fiori appassiti', 'Propagazione: per seme in primavera, a 16-18 °C, per talee erbacee a inizio estate o per propaggine']::text[], 'bozza', true, 'rampicante', 'controllo periodico RHS del 19/11/2026, schede nuove; pagina RHS 325502'),
('b56c71ba-93e5-5b36-8a74-0eb93e5fe878'::uuid, 'd22573b0-c3aa-4f4e-8a02-72979e01bbbd'::uuid, array['RHS (rhs.org.uk) — Verbascum longifolium var. pannosum']::text[], 'Perenne di breve vita della famiglia delle Scrofulariacee, originaria dell''Italia e dei Balcani, che di solito muore dopo aver fiorito. Fusti e foglie sono coperti da un feltro grigio lanoso; in estate alza fino a 2 m spighe di fiori gialli. Resiste bene alla siccità; nei terreni fertili cresce molto e ha bisogno di un sostegno.', 'A short-lived perennial, usually dying back after flowering, with grey-woolly stems and leaves, to around 2m in height.  Spikes of yellow flowers appear in summer', 'it', '{"luce": "Pieno sole", "acqua": "Ben drenato", "terreno": "Calcareo, franco; pH alcalino"}'::jsonb, 'perenne', array['Parassiti: può essere soggetto ai bruchi e al punteruolo della scrofularia; Malattie: può soffrire di oidio', 'Rusticità: minime fino a -20 °C', 'Dimensioni a maturità: altezza 1.5-2.5m, diffusione 0.5-1m', 'Potatura: si tolgono le spighe sfiorite', 'Propagazione: per seme in vaso, in cassone freddo, tra fine primavera e inizio estate, oppure per divisione a inizio primavera o in autunno']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 19/11/2026, schede nuove; pagina RHS 61473');
